SELECT 
FROM session_threads
WHERE workspace_uuid = #{workspaceUUID}
AND session_external_id = #{sessionExternalID}
AND external_id = #{threadExternalID}
AND deleted_at IS NULL

SELECT 
FROM session_threads

    workspace_uuid = #{params.WorkspaceUUID}
    AND session_external_id = #{params.SessionExternalID}
    AND deleted_at IS NULL

        AND (created_at, uuid) < (#{params.Cursor.CreatedAt}, #{params.Cursor.UUID})


ORDER BY created_at DESC, uuid DESC
LIMIT #{params.FetchLimit}

SELECT 
FROM session_threads
WHERE workspace_uuid = #{workspaceUUID}
AND session_external_id = #{sessionExternalID}
AND deleted_at IS NULL
ORDER BY created_at ASC, uuid ASC

mapper.update:
UPDATE session_threads
SET status = #{status}, updated_at = NOW()
WHERE workspace_uuid = #{workspaceUUID}
AND session_external_id = #{sessionExternalID}
AND external_id = #{threadExternalID}
AND deleted_at IS NULL

UPDATE session_threads
SET archived_at = COALESCE(archived_at, NOW()),
    status = 'terminated',
    updated_at = NOW()
WHERE workspace_uuid = #{workspaceUUID}
AND session_external_id = #{sessionExternalID}
AND external_id = #{threadExternalID}
AND deleted_at IS NULL
AND status NOT IN ('running', 'rescheduling')
RETURNING

UPDATE session_threads
SET deleted_at = COALESCE(deleted_at, NOW()), updated_at = NOW()
WHERE workspace_uuid = #{workspaceUUID}
AND session_external_id = #{sessionExternalID}
AND deleted_at IS NULL
